const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Great Lakes region geometry
  const greatLakes = ee.Geometry.Polygon([
    [[-92.5, 41.0], [-92.5, 49.0], [-76.0, 49.0], [-76.0, 41.0], [-92.5, 41.0]]
  ]);

  // 2. Date range for February 11, 2016
  const targetDate = '2016-02-11';
  const startDate = '2016-02-11';
  const endDate = '2016-02-12';

  // 3. Get Landsat 8 imagery
  let collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(greatLakes)
    .filterDate(startDate, endDate);

  const collectionSize = collection.size().getInfo();
  console.log(`Images found for ${targetDate}: ${collectionSize}`);

  if (collectionSize === 0) {
    // Try Landsat 9 as fallback
    collection = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
      .filterBounds(greatLakes)
      .filterDate(startDate, endDate);

    const fallbackSize = collection.size().getInfo();
    console.log(`Landsat 9 fallback images: ${fallbackSize}`);

    if (fallbackSize === 0) {
      console.log('No imagery available for this date and location.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 4. Mosaic all images for the day
  const image = collection.mosaic();

  // 5. Extract cloud information from QA_PIXEL band
  const qaPixel = image.select('QA_PIXEL');

  // Bit 3 is cloud bit in Landsat C02
  const cloudBit = 1 << 3;
  const clouds = qaPixel.bitwiseAnd(cloudBit).neq(0);

  // 6. Count total pixels and cloud pixels
  const stats = clouds.reduceRegion({
    reducer: ee.Reducer.sum().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: greatLakes,
    scale: 3000,
    maxPixels: 1e9
  });

  const statsInfo = stats.getInfo();
  const cloudPixels = statsInfo.sum || 0;
  const totalPixels = statsInfo.count || 0;

  console.log(`Total pixels analyzed: ${totalPixels}`);
  console.log(`Cloud pixels detected: ${cloudPixels}`);

  // 7. Validation and answer
  if (totalPixels === 0) {
    console.log('No valid pixels in region.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (cloudPixels === null || cloudPixels === undefined) {
    console.log('Cloud calculation failed.');
    console.log('<answer>C3</answer>');
    return;
  }

  const cloudPercentage = (cloudPixels / totalPixels * 100).toFixed(2);
  console.log(`Cloud coverage: ${cloudPercentage}%`);

  if (cloudPixels > 0) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
